    inset 0 1px 1.2px 0 rgba(255, 255, 255, 0.85),
    0 8px 26px 0 rgba(0, 0, 0, 0.05),
    0 1px 3px 0 rgba(0, 0, 0, 0.02);

  /* 6. 特殊部件日间色 */
  --card-bg: #ffffff;
  --card-border: rgba(0, 0, 0, 0.08);
  --btn-back-bg: #f2f2f7;
  --knob-holder-bg: #e8e8ed;
  --knob-light: rgba(255, 255, 255, 0.85);
  --knob-dark: rgba(0, 0, 0, 0.08);

  /* 滑块按键背景与弹出面板 */
  --slider-btn-bg: #ffffff;
  --slider-btn-border: 1px solid rgba(0, 0, 0, 0.04);
  --more-options-bg: rgba(255, 255, 255, 0.88);
  --more-options-color: #111111;
  --more-options-divider: rgba(0, 0, 0, 0.06);

  /* 其它功能开关 */
  --typing-bg: transparent;
  --typing-dot-color: #8e8e93;
  --typing-dot-size: 7px;
  --reply-detached-name-suffix: "";

  /*【新增】翻译字幕上下间距控制 */
  --translation-top-gap: -10px;        /* 翻译距离上方气泡的距离 (负数贴近，正数拉开) */
  --translation-bottom-gap: 4px;       /* 翻译距离下方下一条气泡的距离 (越大越远) */

}

/* ---------------------------------------------------------
   🌙【夜间模式变量 (Dark Mode Overrides)】
   跟随系统 prefers-color-scheme 自动触发
   --------------------------------------------------------- */
@media (prefers-color-scheme: dark) {
  :root, body, .chat-detail-screen {
    --chat-bg-color: #000000 !important;
    --bubble-me-bg: #0a84ff !important;
    --bubble-me-color: #ffffff !important;
    --bubble-them-bg: #262629 !important;
    --bubble-them-color: #f5f5f7 !important;
    --bubble-them-border: none !important; /* 👈 夜间绝不要白描边 */
    --text-main: #f5f5f7 !important;
    --text-sub: #98989d !important;

    /* 暗夜高质感液态玻璃 */
    --ios-glass-bg: rgba(28, 28, 30, 0.75) !important;
    --ios-glass-blur: blur(30px) saturate(190%) !important;
    --ios-glass-border: 1px solid rgba(255, 255, 255, 0.12) !important;
    --ios-glass-shadow:
      inset 0 1px 1px 0 rgba(255, 255, 255, 0.18),
      0 12px 32px 0 rgba(0, 0, 0, 0.6) !important;

    --card-bg: #1c1c1e !important;
    --card-border: rgba(255, 255, 255, 0.1) !important;
    --btn-back-bg: #1c1c1e !important;
    --knob-holder-bg: #1e1e20 !important;
    --knob-light: rgba(255, 255, 255, 0.08) !important;
    --knob-dark: rgba(0, 0, 0, 0.5) !important;

    /* 👈 底栏滑块夜间质感 + 更多选项菜单暗夜玻璃 */
    --slider-btn-bg: #2c2c2e !important;
    --slider-btn-border: 1px solid rgba(255, 255, 255, 0.12) !important;
    --more-options-bg: rgba(36, 36, 38, 0.85) !important;
    --more-options-color: #ffffff !important;
    --more-options-divider: rgba(255, 255, 255, 0.08) !important;
  }

  /* 👇 就在这里！直接加在变量块后面、@media 结束的大括号前： */
  .input-box-custom {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
    caret-color: #0a84ff !important; /* 顺手加个 iOS 亮蓝光标，打字更清晰 */
  }

}

/* =========================================================
   1. 隐藏全局头像 (放行顶栏头像，气泡旁头像保持隐藏)
   ========================================================= */
.msg-avatar-them-container,
.msg-avatar-me-container {
  display: none !important;
}
.msg-avatar-them-ghost {
  display: block !important;
}
.header-avatar-container {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
}

/* =========================================================
   2. 消息滚动区：【真实穿透 + 顶端自然融化 + 底部呼吸避让】
   ========================================================= */
.chat-messages-area,
.chat-message-list-custom {
