}

/* =========================================================
   【补丁：纯净表情包/图片 (精准隔离版·绝不误杀正常文本尾巴)】感谢池渝的源代码，基于原来的基础上加上去掉小尾巴伪元素
   ========================================================= */

/* 1. 仅当“气泡本体内部”直接装了图片时，才精准掐灭这个气泡自己的尾巴 (绝不污染其他消息) */
.bubble-me-custom:has(.msg-image-wrapper)::before,
.bubble-me-custom:has(.msg-image-wrapper)::after,
.bubble-them-custom:has(.msg-image-wrapper)::before,
.bubble-them-custom:has(.msg-image-wrapper)::after,
.bubble-me-custom:has(img:not([class*="reply"] img))::before,
.bubble-me-custom:has(img:not([class*="reply"] img))::after,
.bubble-them-custom:has(img:not([class*="reply"] img))::before,
.bubble-them-custom:has(img:not([class*="reply"] img))::after {
  display: none !important;
  content: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
}

/* 2. 仅当气泡内部装了图片时，该气泡外壳全透明、去内边距 */
.bubble-me-custom:has(.msg-image-wrapper),
.bubble-them-custom:has(.msg-image-wrapper),
.bubble-me-custom:has(img:not([class*="reply"] img)),
.bubble-them-custom:has(img:not([class*="reply"] img)) {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

/* 3. 控制聊天区图片/表情包尺寸与圆角 */
.msg-bubble-container img:not([class*="reply"] img) {
  max-width: 110px !important; 
  max-height: 170px !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
  border-radius: 8px !important;
}

/* 发出的图片靠右对齐 */
.msg-me .msg-bubble-container img:not([class*="reply"] img) {
  display: block !important;
  margin-left: auto !important;
  margin-right: 0 !important;
}

/* 收到的图片靠左对齐 */
.msg-them .msg-bubble-container img:not([class*="reply"] img) {
  display: block !important;
  margin-right: auto !important;
  margin-left: 0 !important;
}

.msg-image-wrapper, 
.msg-bubble-container:has(img:not([class*="reply"] img)) {
  height: auto !important;
  min-height: 0 !important;
}

/* 4. 引用框内部的微缩正方形小图保持 28px */
div[class*="reply"] img,
.msg-reply-block-detached img,
.msg-reply-detached-text img {
  width: 28px !important;
  height: 28px !important;
  min-width: 28px !important;
  max-width: 28px !important; 
  max-height: 28px !important;
  object-fit: cover !important; 
  aspect-ratio: 1 / 1 !important; 
  border-radius: 4px !important;
  vertical-align: middle !important;
  display: inline-block !important;
  margin: 0 4px !important;
}

/* =========================================================
   【补丁：终极锁定夜间白心黑圈 (10px标准原版尺寸·绝不缩水)】
   ========================================================= */
@media (prefers-color-scheme: dark) {
  .header-btn-back::before {
    width: 10px !important;                      /* 👈 锁死 10px 绝对尺寸 */
    height: 10px !important;                     /* 👈 锁死 10px 绝对尺寸 */
    right: -2px !important;                      /* 👈 锁死标准坐标 */
    bottom: 0px !important;                      /* 👈 锁死标准坐标 */
    box-sizing: content-box !important;          /* 确保 2px 边框向外撑开，不吃掉 10px 白心 */
    background: #ffffff !important;              /* 👈 纯白心 */
    border: 2px solid #000000 !important;        /* 👈 纯黑圈 */

    border-radius: 50% !important;
