/* =========================================================
   【补丁：夜间模式对方语音条 -> 浅白高光波形与文字】
   ========================================================= */
@media (prefers-color-scheme: dark) {
  /* 1. 变量层夜间反白 */
  :root, body, .chat-detail-screen {
    --voice-them-bar-active: rgba(255, 255, 255, 0.88) !important;
    --voice-them-bar-inactive: rgba(255, 255, 255, 0.28) !important;
  }

  /* 2. 节点层强制浅白上色 (绝不发灰) */
