  .msg-them .voice-duration {
    color: #f5f5f7 !important;
  }

  /* 下载小图标同步提亮 */
  .bubble-them-custom .voice-download-btn,
  .msg-them .voice-download-btn {
    opacity: 0.75 !important;
    filter: invert(1) !important;
  }
}

/* =========================================================
   【补丁：底栏提示条多层阶梯累加引擎 (出几个就精确抬高几层)】
   ========================================================= */

/* 1. 定义单个提示条的标准高度单位 (含 margin 间距正好为 38px) */
:root {
  --bar-step-height: 38px;
}

/* 2. 底栏外壳保持绝对定位穿透 */
.input-area-custom {
  position: absolute !important;
  bottom: 0 !important;
  left: 0 !important;
  right: 0 !important;
  background: transparent !important;
  border: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 10px 12px calc(env(safe-area-inset-bottom, 12px) + 12px) 12px !important;
  margin-top: 0 !important;
  z-index: 100 !important;
  pointer-events: none !important;
}

/* ---------------------------------------------------------
   3. 阶梯累加器：根据实际出现的条目数量逐级向上托起消息
   --------------------------------------------------------- */

/* 【第一阶台阶】：只要出现任意 1 条提示条 (旁白 / 身份 / 回复预览) -> 精准抬高 1 个单位 */
.chat-detail-screen:has(.input-sendas-bar) .chat-messages-area,
.chat-detail-screen:has(.input-sendas-bar) .chat-message-list-custom,
.chat-detail-screen:has(.input-reply-preview-bar) .chat-messages-area,
.chat-detail-screen:has(.input-reply-preview-bar) .chat-message-list-custom,
.chat-detail-screen:has([class*="sendas-bar"]) .chat-messages-area,
.chat-detail-screen:has([class*="sendas-bar"]) .chat-message-list-custom {
  padding-bottom: calc(var(--list-bottom-clearance) + var(--bar-step-height)) !important;
}

/* 【第二阶台阶】：同时出现任意 2 条提示条 -> 精准累加抬高 2 个单位 (38px × 2) */
.chat-detail-screen:has(.input-sendas-bar ~ .input-sendas-bar) .chat-messages-area,
.chat-detail-screen:has(.input-sendas-bar ~ .input-sendas-bar) .chat-message-list-custom,
.chat-detail-screen:has(.input-reply-preview-bar ~ .input-sendas-bar) .chat-messages-area,
.chat-detail-screen:has(.input-reply-preview-bar ~ .input-sendas-bar) .chat-message-list-custom,
.chat-detail-screen:has([class*="sendas-bar"] ~ [class*="sendas-bar"]) .chat-messages-area,
.chat-detail-screen:has([class*="sendas-bar"] ~ [class*="sendas-bar"]) .chat-message-list-custom {
  padding-bottom: calc(var(--list-bottom-clearance) + (var(--bar-step-height) * 2)) !important;
}

/* 【第三阶台阶】：极限状态同时出现 3 条提示条 -> 精准累加抬高 3 个单位 (38px × 3) */
.chat-detail-screen:has(.input-reply-preview-bar ~ .input-sendas-bar ~ .input-sendas-bar) .chat-messages-area,
.chat-detail-screen:has(.input-reply-preview-bar ~ .input-sendas-bar ~ .input-sendas-bar) .chat-message-list-custom,
.chat-detail-screen:has([class*="sendas-bar"] ~ [class*="sendas-bar"] ~ [class*="sendas-bar"]) .chat-messages-area,
.chat-detail-screen:has([class*="sendas-bar"] ~ [class*="sendas-bar"] ~ [class*="sendas-bar"]) .chat-message-list-custom {
  padding-bottom: calc(var(--list-bottom-clearance) + (var(--bar-step-height) * 3)) !important;
}

/* 

4.=========================================================
   【补丁：正在回复预览条高度自适应 (Auto Height 彻底防溢出)】
   ========================================================= */

/* 1. 单行模式条 (旁白/身份)：保持 32px 紧凑高度 */
.input-sendas-bar,
[class*="sendas-bar"] {
  height: 32px !important;
  min-height: 32px !important;
  box-sizing: border-box !important;
  background: var(--ios-glass-bg) !important;
  backdrop-filter: var(--ios-glass-blur) !important;
  -webkit-backdrop-filter: var(--ios-glass-blur) !important;
  border-radius: 12px !important;
  border: var(--ios-glass-border) !important;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.05) !important;
  padding: 0 12px !important;
  margin: 0 4px 6px 4px !important;
  pointer-events: auto !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
}

/* 2. 👇【核心修复】双行回复预览条：解除高度锁死，彻底自适应任何个性字体 */
.input-reply-preview-bar,
[class*="reply-preview-bar"] {
  height: auto !important;          /* 👈 解除高度锁死，允许随字体自由撑开 */
  min-height: 44px !important;      /* 保底高度 */
  box-sizing: border-box !important;
  background: var(--ios-glass-bg) !important;
  backdrop-filter: var(--ios-glass-blur) !important;
  -webkit-backdrop-filter: var(--ios-glass-blur) !important;
  border-radius: 14px !important;
  border: var(--ios-glass-border) !important;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06) !important;
  padding: 6px 12px 6px 8px !important;
  margin: 0 4px 6px 4px !important;
  pointer-events: auto !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  position: relative !important;
}

/* 回复条左侧蓝色竖线：自适应整张卡片的高度 */
.input-reply-preview-bar::before,
[class*="reply-preview-bar"]::before {
  content: "" !important;
  width: 3px !important;
  height: calc(100% - 12px) !important; /* 上下各留 6px 边距，随卡片高度自适应 */
  background-color: var(--bubble-me-bg, #007aff) !important;
  border-radius: 2px !important;
  margin-right: 8px !important;
  flex-shrink: 0 !important;
}

/* 中间两行文字排版区域 */
.input-reply-preview-content,
[class*="reply-preview-content"] {
  flex: 1 !important;
  min-width: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  gap: 2px !important;
}

/* 第一行：「正在回复 某某」 */
.input-reply-preview-name,
[class*="reply-preview-name"] {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif !important;
  font-size: 11.5px !important;
  font-weight: 600 !important;
  color: var(--bubble-me-bg, #007aff) !important;
  line-height: 1.2 !important;
}

/* 第二行：被引用的正文内容 */
.input-reply-preview-text,
[class*="reply-preview-text"] {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif !important;
  font-size: 12.5px !important;
  font-weight: 400 !important;
  color: var(--text-sub, #8e8e93) !important;
  line-height: 1.25 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  max-width: 220px !important;
}

/* 提示条内部文字 */
.input-sendas-label,
[class*="sendas-label"] {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  color: var(--text-main) !important;
  letter-spacing: -0.2px !important;
  line-height: 1 !important;
}

.input-sendas-char-bar .input-sendas-label,
[class*="sendas-char"] [class*="sendas-label"] {
  color: var(--bubble-me-bg) !important;
  font-weight: 600 !important;
}

.input-sendas-narration-bar .input-sendas-label,
[class*="sendas-narration"] [class*="sendas-label"] {
  color: var(--text-sub) !important;
  font-style: italic !important;
}

/* 右侧关闭「×」按键 (强制在自适应卡片中绝对垂直居中) */
.input-sendas-close,
.input-reply-preview-close,
[class*="sendas-close"],
[class*="reply-preview-close"] {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 20px !important;
  height: 20px !important;
  min-width: 20px !important;
  min-height: 20px !important;
  padding: 0 !important;
  margin: 0 !important;
  line-height: 1 !important;
  font-size: 15px !important;
  color: var(--text-sub) !important;
  opacity: 0.65 !important;
  cursor: pointer !important;
  align-self: center !important; /* 👈 随卡片自动居中 */
  flex-shrink: 0 !important;
}
.input-sendas-close:active,
.input-reply-preview-close:active {
  opacity: 1 !important;
  transform: scale(0.9) !important;
}

/* ===== 锁死发送键大小，强制关闭软件自带的动画by烧酒酒 ===== */
.send-btn-custom,
.send-btn-custom:active,
.send-btn-custom:focus {
    transform: scale(1) translateY(0px) !important;
    transition: none !important; /* 彻底关掉自带的过渡动画 */
    animation: none !important;  /* 彻底关掉自带的帧动画 */
}

/* ==============================================================
   [通用补丁] 强制日间纯白 / 夜间纯黑背景by燒酒
   使用说明：请将此段代码放在整个 CSS 的最末尾
   ============================================================== */

/* 1. 默认（日间）强制纯白背景，并清除所有背景图与毛玻璃 */
:root {
  --chat-bg-color: #f7f7f8 !important;       /* 强制白底 */
  --chat-bg-image: none !important;          /* 屏蔽壁纸/背景图 */
  --chat-bg-overlay: transparent !important; /* 清除叠加层 */
  --chat-bg-blur: 0px !important;            /* 清除背景模糊 */
}

/* 2. 当系统切换到深色模式时，强制纯黑背景 */
@media (prefers-color-scheme: dark) {
  :root {
    --chat-bg-color: #000000 !important;       /* 强制黑底 */
    --chat-bg-image: none !important;          /* 屏蔽壁纸/背景图 */
    --chat-bg-overlay: transparent !important; /* 清除叠加层 */
    --chat-bg-blur: 0px !important;            /* 清除背景模糊 */
  }
}

