  font-size:17px!important;
  font-weight:500!important;
  color:var(--chat-header-title-color)!important;
}

/* 顶栏返回 / 更多图标 */
.header-btn-back svg,
.header-btn-info svg{display:none!important;}
.header-btn-back::before{
  content:"";
  display:block;
  width:20px;
  height:22px;
  -webkit-mask-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M15 20l-8-8 8-8"/></svg>');
  mask-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M15 20l-8-8 8-8"/></svg>');
  -webkit-mask-size:contain;
  mask-size:contain;
  -webkit-mask-repeat:no-repeat;
  mask-repeat:no-repeat;
  -webkit-mask-position:center;
  mask-position:center;
  background-color:var(--chat-header-title-color)!important;
  transform:translate(var(--btn-back-translate-x),var(--btn-back-translate-y))!important;
}
.header-btn-info::before{
  content:"";
  display:block;
  width:24px;
  height:24px;
  -webkit-mask-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="black"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg>');
  mask-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="black"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg>');
  -webkit-mask-size:contain;
  mask-size:contain;
  -webkit-mask-repeat:no-repeat;
  mask-repeat:no-repeat;
  -webkit-mask-position:center;
  mask-position:center;
  background-color:var(--chat-header-title-color)!important;
  transform:translate(var(--btn-info-translate-x),var(--btn-info-translate-y))!important;
}

/* 顶栏未读 */
.nuo-chat-header-unread-dot{
  --chat-header-unread-size:0!important;
  display:none!important;
}
.nuo-chat-header-unread-num{
  --chat-header-unread-num-top:var(--unread-num-top)!important;
  --chat-header-unread-num-left:var(--unread-num-left)!important;
  --chat-header-unread-num-size:var(--unread-num-font-size)!important;
  --chat-header-unread-num-weight:var(--unread-num-font-weight)!important;
  --chat-header-unread-num-padding:var(--unread-num-padding)!important;
  --chat-header-unread-num-height:var(--unread-num-height)!important;
  --chat-header-unread-num-radius:999px!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  --chat-header-unread-num-border:none!important;
  --chat-header-unread-num-shadow:none!important;
}

/* 对方正在输入 */
.chat-detail-screen:has(.stop-btn-custom) .chat-header-title{
  color:transparent!important;
}
.chat-detail-screen:has(.stop-btn-custom) .chat-header-title::before{
  content:"对方正在输入...";
  position:absolute;
  left:50%;
  transform:translateX(-50%);
  color:var(--chat-header-title-color)!important;
  font-size:var(--chat-header-title-size)!important;
  font-weight:var(--font-weight)!important;
  white-space:nowrap;
}
.nuo-typing-indicator{display:none!important;}

/* =================================== */
/* 底栏 */
/* =================================== */
.input-area-custom{
  padding-top:var(--input-top-space)!important;
  padding-bottom:var(--bottom-lift-space)!important;
}
.input-action-bar-custom,
.input-action-bar-custom > *,
.input-action-bar-custom .input-box-custom,
.input-box-custom,
.input-box-custom:focus,
.input-box-custom:disabled,
.input-box-custom:-webkit-autofill,
.input-box-custom:-webkit-autofill:focus{
  background-color:transparent!important;
  background-image:none!important;
  background:transparent!important;
  border:none!important;
  box-shadow:none!important;
  outline:none!important;
  -webkit-box-shadow:none!important;
  -webkit-background-clip:unset!important;
}
.input-box-custom::-webkit-input-placeholder{
  color:transparent!important;
  font-size:0px!important;
  opacity:0!important;
  -webkit-text-fill-color:transparent!important;
  visibility:hidden!important;
}
.input-box-custom::placeholder{
  color:transparent!important;
  font-size:0px!important;
  opacity:0!important;
  -webkit-text-fill-color:transparent!important;
  visibility:hidden!important;
}

/* 底栏左侧语音图标 */
.input-btn-plus svg{display:none!important;}
.input-btn-plus::before{
  content:"";
  display:block;
  width:var(--voice-btn-size)!important;
  height:var(--voice-btn-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/17ec3907-e615-4349-a269-9f716cf59489.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  transform:translate(var(--voice-btn-x),var(--voice-btn-y))!important;
}

/* 底栏幽灵线框 */
.input-action-bar-custom{
  position:relative!important;
  z-index:1!important;
}
.input-action-bar-custom::before{
  content:"";
  position:absolute;
  top:var(--box-top-offset)!important;
  bottom:var(--box-bottom-offset)!important;
  left:var(--box-left-space)!important;
  right:var(--box-right-space)!important;
  border:var(--box-border-width) solid var(--box-border-color)!important;
  border-radius:var(--box-border-radius)!important;
  background-color:var(--box-bg-color)!important;
  border-color:var(--box-border-color)!important;
  pointer-events:none!important;
  z-index:-1!important;
}

/* 底栏输入框 */
.input-box-custom,
.input-box-custom *,
.input-action-bar-custom .input-box-custom,
.input-action-bar-custom .input-box-custom *{
  color:var(--input-text-color)!important;
  -webkit-text-fill-color:var(--input-text-color)!important;
  caret-color:var(--input-caret-color)!important;
}
.input-box-custom{
  margin-left:var(--input-box-pull-left)!important;
  margin-right:var(--input-box-pull-right)!important;
  text-align:left!important;
  padding-left:var(--input-text-padding-left)!important;
  padding-right:10px!important;
clip-path: inset(var(--box-top-offset) 0 var(--box-bottom-offset) 0) !important;
}
.input-box-custom::selection,
.input-box-custom *::selection{
  background-color:var(--input-selection-bg)!important;
  color:var(--input-text-color)!important;
  -webkit-text-fill-color:var(--input-text-color)!important;
}
.input-box-custom::-moz-selection,
.input-box-custom *::-moz-selection{
  background-color:var(--input-selection-bg)!important;
  color:var(--input-text-color)!important;
}

/* 底栏右侧按键 */
.input-btn-mic svg,
.input-btn-sticker svg,
.input-btn-ai svg,
.send-btn-custom svg{display:none!important;}
.input-btn-mic{transform:translate(var(--btn-mic-x),var(--btn-mic-y))!important;}
.input-btn-sticker{transform:translate(var(--btn-sticker-x),var(--btn-sticker-y))!important;}
.input-btn-ai,
.send-btn-custom{transform:translate(var(--btn-ai-send-x),var(--btn-ai-send-y))!important;}
.input-btn-mic::before{
  content:"";
  display:block;
  width:var(--right-mic-size)!important;
  height:var(--right-mic-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/59f469f5-0c70-43ce-ae1e-4c633e9a4e9a.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
}
.input-btn-sticker::before{
  content:"";
  display:block;
  width:var(--right-btn-size)!important;
  height:var(--right-btn-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/da835c40-d3c7-4462-ad4b-5c598284837b.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
}
.input-btn-ai::before,
.send-btn-custom::before{
  content:"";
  display:block;
  width:var(--right-btn-size)!important;
  height:var(--right-btn-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/4f7329f5-0fbc-4871-98ea-b2223db71efb.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
}

/* 打字状态监听 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)){
  align-items:flex-end!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-plus,
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-mic,
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-sticker,
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai,
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .send-btn-custom{
  margin-bottom:var(--typing-btn-bottom)!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai{
  pointer-events:none!important;
  transform:translate(var(--fake-sticker-x),var(--fake-sticker-y))!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai::before{
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/da835c40-d3c7-4462-ad4b-5c598284837b.png')!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .send-btn-custom{
  transform:translate(var(--real-send-x),var(--real-send-y))!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-box-custom{
  min-height:40px!important;
  padding-top:10px!important;
  padding-bottom:10px!important;
}

/* AI 生成时底栏伪装 */
.stop-btn-custom{
  background:transparent!important;
  box-shadow:none!important;
  color:transparent!important;
  position:relative!important;
}
.stop-btn-custom svg{display:none!important;}
.chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::before{
  content:"";
  display:block;
  width:var(--right-btn-size)!important;
  height:var(--right-btn-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/bfefc490-ba9e-4552-9926-abbb5b5d7cbe.png')!important;
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  position:absolute!important;
  top:var(--gen-icon-y)!important;
  left:var(--gen-plus-x)!important;
  transform:translateY(-50%)!important;
  pointer-events:none!important;
}
.chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::after{
  content:"";
  display:block;
  width:28px!important;
  height:28px!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/da835c40-d3c7-4462-ad4b-5c598284837b.png')!important;
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  position:absolute!important;
  top:var(--gen-sticker-y)!important;
  left:var(--gen-sticker-x)!important;
  transform:translateY(-50%)!important;
  pointer-events:none!important;
}
.chat-detail-screen:has(.stop-btn-custom) .input-action-bar-custom::after{
  content:"";
  display:block;
  width:17.9px!important;
  height:17.9px!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/59f469f5-0c70-43ce-ae1e-4c633e9a4e9a.png')!important;
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  position:absolute!important;
  top:var(--gen-mic-y)!important;
  right:calc(var(--gen-mic-x) * -1)!important;
  transform:translateY(-50%)!important;
  pointer-events:none!important;
  z-index:10!important;
}

/* 禁用左侧菜单键旋转 */
.input-btn-plus,
.input-btn-plus:active,
.input-btn-plus:focus,
.input-btn-plus[class*="open"],
.input-btn-plus[class*="active"],
.input-action-bar-custom:has(.more-options-popup) .input-btn-plus{
  transform:none!important;
  rotate:0deg!important;
  transition:none!important;
}

/* 夜间底栏防白线 */
@media (prefers-color-scheme: dark) {
  body .input-area-custom,
  body .input-area-custom > *,
  body .input-action-bar-custom{
    background-color:#1E1E1E!important;
    background-image:linear-gradient(#1E1E1E,#1E1E1E)!important;
    background-size:100% 100%!important;
    background-repeat:no-repeat!important;
    backdrop-filter:none!important;
    -webkit-backdrop-filter:none!important;
    box-shadow:none!important;
    border-top:none!important;
    border-top-color:transparent!important;
  }

  /* 夜间图标防刺眼 */
  body .input-btn-plus::before{
    filter:invert(1) opacity(var(--dark-icon-opacity))!important;
  }
  body .input-btn-mic::before,
  body .input-btn-sticker::before,
  body .input-btn-ai::before,
  body .send-btn-custom::before{
    filter:invert(1) opacity(var(--dark-icon-opacity))!important;
  }
  body .chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::before,
  body .chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::after,
  body .chat-detail-screen:has(.stop-btn-custom) .input-action-bar-custom::after{
    filter:invert(1) opacity(var(--dark-icon-opacity))!important;
  }
}

/* =================================== */
/* 气泡微信化 */
/* =================================== */
:root{
  --bubble-me-padding:8px 11px;
  --bubble-them-padding:8px 11px;
  --wechat-bubble-radius:4px;
  --bubble-tail-width:15.5px;
  --bubble-tail-height:15.5px;
  --bubble-tail-top:11px;
  --bubble-me-tail-right:-3px;
  --bubble-them-tail-left:-3px;
}
.bubble-me-custom,
.bubble-them-custom{
  border-radius:var(--wechat-bubble-radius)!important;
  position:relative!important;
  overflow:visible!important;
  box-shadow:none!important;
  border:none!important;
}
/* 我方气泡小角：纯 CSS 圆角菱形 */
.bubble-me-custom::before{
  content:"" !important;
  display:block !important;
  position:absolute !important;
  top:var(--bubble-tail-top)!important;
  right:var(--bubble-me-tail-right)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-me-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important; 
}
/* 对方气泡小角：纯 CSS 圆角菱形 */
.bubble-them-custom::before{
  content:"" !important;
  display:block !important;
  position:absolute !important;
  top:var(--bubble-tail-top)!important;
  left:var(--bubble-them-tail-left)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-them-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
}
.bubble-me-custom,
.bubble-them-custom {
    max-width: 72vw !important; 
    box-sizing: border-box !important;
    word-wrap: break-word !important;
    word-break: break-word !important; /* 👈 恢复成这个，保护英文单词完整 */
    /* 👇 保护你心心念念的中文“左右对称” */
    text-align: justify !important;
    text-justify: inter-ideograph !important;
}

/* =================================== */
/* 引用条 */
/* =================================== */
:root{
  --reply-bar-bg:var(--reply-detached-bg);
  --reply-bar-border:var(--reply-detached-border);
  --reply-bar-radius:var(--reply-detached-radius);
  --reply-bar-padding:1px 4px;
  --reply-bar-margin-bottom:5px;
  --reply-bar-shadow:none;
  --reply-bar-backdrop:none;
  --reply-bar-content-direction:row;
  --reply-bar-content-gap:2px;
  --reply-bar-content-padding-left:0;
  --reply-bar-accent-border:none;
  --reply-bar-name-color:var(--reply-detached-name-color);
  --reply-bar-name-size:13px;
  --reply-bar-name-weight:normal;
  --reply-bar-text-color:var(--reply-detached-text-color);
  --reply-bar-text-size:13px;

  --reply-detached-radius:4px;
  --reply-detached-padding:5px 8px;
  --reply-detached-margin-top:4px;
  --reply-detached-name-size:11.5px;
  --reply-detached-text-size:11.5px;
  --reply-detached-border-left:none;
  --reply-detached-backdrop:blur(10px) saturate(180%);
}
.msg-reply-block{display:none!important;}
.msg-reply-block-detached{display:flex!important;}

/* 引用框防溢出 */
.msg-reply-block-detached{
  display:flex!important;
  align-items:center!important;
  flex-direction:row!important;
  flex-wrap:nowrap!important;
  width:fit-content!important;
  max-width:calc(100vw - 180px)!important;
  min-width:0!important;
  box-sizing:border-box!important;
  overflow:hidden!important;
}
.msg-me .msg-reply-block-detached img,
.msg-them .msg-reply-block-detached img,
.msg-reply-block-detached img{
  width:30px!important;
  height:30px!important;
  min-width:30px!important;
  min-height:30px!important;
  max-width:30px!important;
  max-height:30px!important;
  object-fit:cover!important;
  border-radius:4px!important;
  flex-shrink:0!important;
  margin:0!important;
  padding:0!important;
  display:block!important;
  position:static!important;
  transform:none!important;
}
.msg-reply-detached-text,
.msg-reply-detached-content,
.msg-reply-block-detached span:not(.msg-reply-detached-name){
  flex:1 1 auto!important;
  min-width:0!important;
  overflow:hidden!important;
  text-overflow:ellipsis!important;
  white-space:nowrap!important;
  word-break:break-all!important;
}
.msg-reply-detached-name,
.msg-reply-detached-text{
  align-self:flex-start!important;
  margin-top:1px!important;
  line-height:1.1!important;
}

/* =================================== */
/* 输入框引用预览 */
/* =================================== */
.input-reply-preview-bar{
  margin-left:30px!important;
  margin-right:66px!important;
  width:auto!important;
  border-radius:5px!important;
}
.input-area-custom{
  display:flex!important;
  flex-direction:column!important;
}
.input-action-bar-custom{order:1!important;}
.input-reply-preview-bar{
  order:2!important;
  margin-bottom:0!important;
  margin-top:0px!important;
}
.input-reply-preview-content{
  display:flex!important;
  flex-direction:row!important;
  align-items:center!important;
  width:100%!important;
  overflow:hidden!important;
}
.input-reply-preview-name{
  white-space:nowrap!important;
  flex-shrink:0!important;
  color:var(--reply-detached-name-color)!important;
margin-left: -54px !important; 
}
.input-reply-preview-name::after{
  content:"："!important;
}
.input-reply-preview-text{
  white-space:nowrap!important;
  overflow:hidden!important;
  text-overflow:ellipsis!important;
  margin-left:-3.5px!important;
}
.input-reply-preview-close{margin-left:auto!important;}

@media (prefers-color-scheme: light) {
  body .input-reply-preview-bar{
    background:var(--input-reply-bar-bg)!important;
    background-color:var(--input-reply-bar-bg)!important;
    background-image:none!important;
    border:var(--input-reply-bar-border)!important;
    backdrop-filter:blur(10px) saturate(180%)!important;
    -webkit-backdrop-filter:blur(10px) saturate(180%)!important;
  }
}
@media (prefers-color-scheme: dark) {
  body .input-reply-preview-bar{
    background:var(--input-reply-bar-bg)!important;
    background-color:var(--input-reply-bar-bg)!important;
    background-image:none!important;
    border:var(--input-reply-bar-border)!important;
    backdrop-filter:blur(10px) saturate(180%)!important;
    -webkit-backdrop-filter:blur(10px) saturate(180%)!important;
  }
}
body .input-reply-preview-name,
body .input-reply-preview-name::after{
  color:var(--input-reply-bar-name-color)!important;
  -webkit-text-fill-color:var(--input-reply-bar-name-color)!important;
}
body .input-reply-preview-text{
  color:var(--input-reply-bar-text-color)!important;
  -webkit-text-fill-color:var(--input-reply-bar-text-color)!important;
}
body .input-reply-preview-close,
body .input-reply-preview-close svg,
body .input-reply-preview-close svg *{
  color:var(--input-reply-bar-close-color)!important;
  stroke:var(--input-reply-bar-close-color)!important;
  fill:var(--input-reply-bar-close-color)!important;
}
/* =================================== */
/* 图片 / 表情 / 非文字消息去气泡  */
/* =================================== */
.bubble-me-custom img,
.bubble-them-custom img,
.msg-plain-me img,
.msg-plain-them img{
  max-width:110px!important;
  max-height:110px!important;
  width:auto!important;
  height:auto!important;
  object-fit:contain!important;
border-radius:5px!important;
}
:is(.sticker-container, [class*="sticker"], [class*="emoji"]) img {
  background-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
}
